SET NAMES utf8mb4;

UPDATE `projects_i18n` SET
  `summary` = 'Üretim sektörü için sıfırdan geliştirilen çok kullanıcılı ERP: stok, sipariş, üretim planlama ve operasyon yönetimi tek panelde.',
  `meta_title` = 'Üretim ERP: Paspaş Vaka Çalışması | GZL Teknoloji',
  `meta_description` = 'Üretim ERP vaka çalışması: stok, sipariş, üretim planlama ve operasyon takibi tek panelde toplandı; elektronik tablo düzeni kalıcı bir sisteme taşındı.',
  `content` = '{"description":"Üretim sektörü için sıfırdan geliştirilen çok kullanıcılı ERP: stok, sipariş, üretim planlama ve operasyon yönetimi tek panelde.","key_features":["Stok ve depo takibi","Sipariş ve üretim planlama","İş emri ve operasyon kaydı","Rol bazlı yetkilendirme","Yönetim raporları"],"technologies_used":["Next.js","Fastify","Drizzle ORM","MySQL","Bun","Zod","JWT"],"case_study":{"challenge":"En büyük sorun veri değil, verinin iki kez girilmesiydi. Depodaki hareket sisteme geç yansıdığı için üretim planı gerçek stoğu göstermiyor, eksik malzeme ancak üretim başlayınca fark ediliyordu. Hazır ERP denemeleri ise firmanın kendi üretim akışına uymadığı için yarım kalmıştı.","approach":"Tüm modülleri aynı anda teslim etmek yerine en pahalı sorunla, stok ve iş emri ilişkisiyle başladık. İlk sürüm birkaç hafta içinde canlıya alındı ve gerçek kullanımın gösterdiği eksikler sonraki modüllerin kapsamını belirledi.","outcome":"Üretim planı artık gerçek stok üzerinden hesaplanıyor; aynı kaydın iki yere girilmesi ortadan kalktı. Yönetim raporu ay sonunda elle birleştirilen bir dosya olmaktan çıkıp panelden anlık alınabilir hale geldi."},"html":"<p>Üretim ERP ihtiyacı, hazır paketlerin sunduğu genel akışların bu firmanın süreçlerine uymamasıyla başladı. GZL Teknoloji olarak stok, sipariş, üretim planlama ve operasyon takibini tek panelde toplayan sistemi sıfırdan geliştirdik.</p>\\n<h2>Proje hakkında</h2>\\n<p>Firma üretimini elektronik tablolarla ve bölüm bölüm tutulan defterlerle yönetiyordu. Aynı veri hem depoda hem muhasebede ayrı ayrı giriliyor, ay sonunda raporlar elle birleştiriliyordu. Proje, bu dağınık düzeni tek bir kayıt sistemine taşımak için başlatıldı.</p>\\n<h2>üretim ERP projesinde çözülen sorun</h2>\\n<p>En büyük sorun veri değil, verinin iki kez girilmesiydi. Depodaki hareket sisteme geç yansıdığı için üretim planı gerçek stoğu göstermiyor, eksik malzeme ancak üretim başlayınca fark ediliyordu. Hazır ERP denemeleri ise firmanın kendi üretim akışına uymadığı için yarım kalmıştı.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Tüm modülleri aynı anda teslim etmek yerine en pahalı sorunla, stok ve iş emri ilişkisiyle başladık. İlk sürüm birkaç hafta içinde canlıya alındı ve gerçek kullanımın gösterdiği eksikler sonraki modüllerin kapsamını belirledi.</p>\\n<ul><li>Mevcut süreçler sahada izlendi ve akış şemaları çıkarıldı</li><li>Stok ve iş emri modülü önce canlıya alındı</li><li>Sipariş, cari ve raporlama modülleri sırayla eklendi</li><li>Geçmiş veri aktarıldı, ekip eğitimi tamamlandı</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Üretim planı artık gerçek stok üzerinden hesaplanıyor; aynı kaydın iki yere girilmesi ortadan kalktı. Yönetim raporu ay sonunda elle birleştirilen bir dosya olmaktan çıkıp panelden anlık alınabilir hale geldi.</p>\\n<ul><li>Tek kayıt noktası: depo, üretim ve sipariş aynı veriyi görüyor</li><li>İş emri durumu anlık izlenebiliyor</li><li>Kullanıcı sayısı arttıkça artan lisans maliyeti yok</li><li>Kaynak kodu ve veritabanı firmaya teslim edildi</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>Next.js</li><li>Fastify</li><li>Drizzle ORM</li><li>MySQL</li><li>Bun</li><li>Zod</li><li>JWT</li></ul>\\n<p>Sistem 2026 itibarıyla üretimde kullanılıyor ve bakım kapsamında güncelleniyor. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>Hazır ERP yerine neden özel geliştirme?</h3>\\n<p>Firmanın üretim akışı standart paketlerin varsaydığı sıradan farklı ilerliyordu. Pakete uymak için süreci değiştirmek, yazılımı sürece uydurmaktan daha pahalıya çıkıyordu.</p>\\n<h3>Proje ne kadar sürdü?</h3>\\n<p>İlk çalışan sürüm 4-6 hafta içinde canlıya alındı; tüm modüllerin tamamlanması birkaç aya yayıldı. Bu yaklaşım firmanın erken fayda görmesini sağladı.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/firmaya-ozel-erp-yazilimi\\">Firmaya özel ERP</a> · <a href=\\"/tr/hizmetler/ozel-yazilim-nextjs-fastify\\">Özel yazılım geliştirme</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'paspas-erp-uretim-ve-operasyon-yonetim-sistemi';

