  WHERE i.slug = 'paspas-erp-uretim-ve-operasyon-yonetim-sistemi';

UPDATE `projects_i18n` SET
  `summary` = 'Ensotek B2B platformu: katalog, teklif, sipariş ve dokümantasyon modüllerini tek altyapıda toplayan çok kiracılı ve çok dilli sistem.',
  `meta_title` = 'Ensotek B2B Platformu: Çok Kiracılı Kurulum | GZL',
  `meta_description` = 'B2B platform vaka çalışması: katalog, teklif, sipariş ve dokümantasyon modülleriyle çok dilli, çok kiracılı bir kurumsal sistem kuruldu.',
  `content` = '{"description":"Ensotek B2B platformu: katalog, teklif, sipariş ve dokümantasyon modüllerini tek altyapıda toplayan çok kiracılı ve çok dilli sistem.","key_features":["Çok kiracılı (multi-tenant) mimari","Katalog, teklif ve sipariş akışı","Teknik dokümantasyon yönetimi","Rol tabanlı yönetim paneli","Çok dilli içerik"],"technologies_used":["Next.js","TypeScript","Fastify","MySQL","Docker","Nginx"],"case_study":{"challenge":"Aynı ürünün her pazarda farklı adı, farklı teknik belgesi ve farklı fiyatı vardı. Bu farklılıkları tek bir katalogda kaybetmeden yönetmek gerekiyordu; ayrıca her bayinin yalnızca kendi verisini görmesi şarttı.","approach":"Veri modelini kiracı (tenant) ve dil ekseninde ayırdık: ürün tek kayıt, çevirisi ve pazara özel alanları ayrı. Yetkilendirme kiracı düzeyinde kurgulandı, böylece bayi kendi dışındaki hiçbir kayda erişemiyor.","outcome":"Katalog artık tek kaynaktan yönetiliyor; bayiye giden belge her zaman güncel sürüm. Teklif süreci e-posta zincirinden çıkıp izlenebilir bir akışa dönüştü."},"html":"<p>B2B platform ihtiyacı, ihracat yapan bir sanayi firmasının katalog, teklif ve dokümantasyon süreçlerini tek yerde toplama isteğiyle doğdu. GZL Teknoloji olarak çok kiracılı ve çok dilli bir altyapı kurduk.</p>\\n<h2>Proje hakkında</h2>\\n<p>Firma ürün kataloğunu PDF, teklifleri elektronik tablo, teknik belgeleri ise e-posta ekleriyle yönetiyordu. Farklı pazarlardaki bayiler aynı belgenin farklı sürümlerini kullanıyordu. Platform, tek doğru kaynağı oluşturmak için geliştirildi.</p>\\n<h2>Ensotek B2B platformu projesinde çözülen sorun</h2>\\n<p>Aynı ürünün her pazarda farklı adı, farklı teknik belgesi ve farklı fiyatı vardı. Bu farklılıkları tek bir katalogda kaybetmeden yönetmek gerekiyordu; ayrıca her bayinin yalnızca kendi verisini görmesi şarttı.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Veri modelini kiracı (tenant) ve dil ekseninde ayırdık: ürün tek kayıt, çevirisi ve pazara özel alanları ayrı. Yetkilendirme kiracı düzeyinde kurgulandı, böylece bayi kendi dışındaki hiçbir kayda erişemiyor.</p>\\n<ul><li>Ürün ve belge envanteri çıkarıldı</li><li>Çok kiracılı veri modeli ve yetki katmanı kuruldu</li><li>Katalog, teklif ve dokümantasyon modülleri geliştirildi</li><li>Çok dilli içerik aktarımı yapıldı</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Katalog artık tek kaynaktan yönetiliyor; bayiye giden belge her zaman güncel sürüm. Teklif süreci e-posta zincirinden çıkıp izlenebilir bir akışa dönüştü.</p>\\n<ul><li>Tek doğru kaynak: belge sürüm karmaşası sona erdi</li><li>Bayi bazlı erişim ayrımı</li><li>Çok dilli katalog tek panelden yönetiliyor</li><li>Yeni pazar eklemek yeni kurulum gerektirmiyor</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>Next.js</li><li>TypeScript</li><li>Fastify</li><li>MySQL</li><li>Docker</li><li>Nginx</li></ul>\\n<p>Platform 2026 itibarıyla canlıda ve yeni pazarlar eklendikçe genişletiliyor. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>Çok kiracılı mimari ne kazandırdı?</h3>\\n<p>Yeni bir bayi ya da pazar eklendiğinde ayrı bir kurulum ve ayrı bir bakım yükü doğmuyor; aynı sistem üzerinde izole bir alan açılıyor.</p>\\n<h3>Mevcut belgeler aktarıldı mı?</h3>\\n<p>Evet. Katalog ve teknik belgeler toplu olarak aktarıldı; aktarım öncesi sürüm temizliği ayrı bir adım olarak yürütüldü.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/ozel-yazilim-nextjs-fastify\\">Özel yazılım geliştirme</a> · <a href=\\"/tr/hizmetler/kurumsal-web-sitesi\\">Kurumsal web sitesi</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'ensotek-multi-tenant-b2b-saas-metahub';

UPDATE `projects` pr
  JOIN `projects_i18n` i ON i.project_id = pr.id AND i.locale = 'tr'
  SET pr.`client_name` = 'Ensotek',
