UPDATE `projects_i18n` SET
  `summary` = 'Amazon kategorilerini tarayıp çok boyutlu risk skoru ve gerekçeli karar üreten ürün araştırma radarı.',
  `meta_title` = 'Amazon Ticari Radar: AI Karar Motoru | GZL Teknoloji',
  `meta_description` = 'Amazon ticari radar vaka çalışması: kategori taraması, fiyat geçmişi ve çok boyutlu risk skoru açıklanabilir bir al/bekle/uzak dur kararına dönüştürüldü.',
  `content` = '{"description":"Amazon kategorilerini tarayıp çok boyutlu risk skoru ve gerekçeli karar üreten ürün araştırma radarı.","key_features":["Anahtar kelime ve ASIN bazlı kategori taraması","Fiyat geçmişi ve satıcı sayısı takibi","Beş boyutlu risk ve fırsat skoru","Büyük dil modeliyle gerekçeli karar notu","Dışa aktarılabilir yönetici özeti"],"technologies_used":["TypeScript","Bun","Next.js","Fastify","MySQL","Playwright","Keepa API"],"case_study":{"challenge":"Ham veri toplamak sorunun küçük kısmıydı. Asıl zorluk aynı ürünün farklı listelemelerde tekrar etmesi ve toplanan sayıların tek başına bir şey söylememesiydi: hangi ürünün riskli, hangisinin fırsat olduğu insan yorumuna kalıyordu.","approach":"Tekilleştirme katmanını ayrı kurduk; ardından beş boyutlu bir skor tanımladık ve skorun gerekçesini düz metinle açıklayan bir yorum katmanı ekledik. Böylece çıktı bir sayı değil, savunulabilir bir karar oldu.","outcome":"Araştırma süresi saatlerden dakikalara indi; her karar, hangi sinyalden geldiği görülebilir biçimde kayıt altında. Aynı ürüne farklı zamanlarda bakıldığında kararın neden değiştiği izlenebiliyor."},"html":"<p>Amazon ticari radar, pazar yerinde ürün seçimini sezgiden çıkarıp ölçülebilir bir karara dönüştürmek için geliştirildi. Kategori taraması, fiyat geçmişi ve risk skorlaması tek panelde birleşiyor.</p>\\n<h2>Proje hakkında</h2>\\n<p>Pazar yerinde ürün araştırması genellikle birkaç ekran görüntüsü ve kişisel yorumla yapılır. Oysa karar için gereken veri açıktır: fiyat geçmişi, satıcı sayısı, değerlendirme eğilimi ve kategori derinliği. Proje bu verileri düzenli toplayıp karşılaştırılabilir hale getirmek için başladı.</p>\\n<h2>Amazon ticari radar projesinde çözülen sorun</h2>\\n<p>Ham veri toplamak sorunun küçük kısmıydı. Asıl zorluk aynı ürünün farklı listelemelerde tekrar etmesi ve toplanan sayıların tek başına bir şey söylememesiydi: hangi ürünün riskli, hangisinin fırsat olduğu insan yorumuna kalıyordu.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Tekilleştirme katmanını ayrı kurduk; ardından beş boyutlu bir skor tanımladık ve skorun gerekçesini düz metinle açıklayan bir yorum katmanı ekledik. Böylece çıktı bir sayı değil, savunulabilir bir karar oldu.</p>\\n<ul><li>Kategori ve anahtar kelime bazlı tarama altyapısı kuruldu</li><li>ASIN tekilleştirme ve varyant eşleştirme yazıldı</li><li>Fiyat geçmişi kaynağı entegre edildi</li><li>Skorlama ağırlıkları ve gerekçe katmanı eklendi</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Araştırma süresi saatlerden dakikalara indi; her karar, hangi sinyalden geldiği görülebilir biçimde kayıt altında. Aynı ürüne farklı zamanlarda bakıldığında kararın neden değiştiği izlenebiliyor.</p>\\n<ul><li>Tekilleştirme sayesinde tekrar eden kayıtlar ayıklanıyor</li><li>Karar gerekçesiyle birlikte üretiliyor</li><li>Periyodik tarama ile fiyat değişimleri uyarıya dönüşüyor</li><li>Sonuçlar tablo olarak dışa aktarılabiliyor</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>TypeScript</li><li>Bun</li><li>Next.js</li><li>Fastify</li><li>MySQL</li><li>Playwright</li><li>Keepa API</li></ul>\\n<p>Radar 2026 itibarıyla iç kullanımda çalışıyor ve yeni pazar yerleri için genişletiliyor. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>Veri nereden toplanıyor?</h3>\\n<p>Yalnızca herkese açık sayfalar ve resmî arayüzler kullanılıyor; makul aralıklarla, platformun teknik sınırlarını zorlamadan.</p>\\n<h3>Skor ağırlıkları değiştirilebiliyor mu?</h3>\\n<p>Evet. Kategoriye göre ağırlıklar panelden ayarlanıyor; aynı veri farklı ticari önceliklerle farklı sıralanabiliyor.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/amazon-fiyat-scraping-sistemi\\">Amazon fiyat takip sistemi</a> · <a href=\\"/tr/hizmetler/ai-ml-veri-tahmin-platformu\\">Veri tahmin platformu</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'amozon-amazon-ticari-radar-ai-karar-motoru';

