UPDATE `projects_i18n` SET
  `summary` = 'İhracat odaklı B2B sitesi: dile göre adres yapısı, yapılandırılmış veri ve performans kurulumu tek projede.',
  `meta_title` = 'İhracat Odaklı B2B Sitesi: GEO ve SEO Kurulumu | GZL',
  `meta_description` = 'Çok dilli B2B sitesi vaka çalışması: dile göre adres yapısı, yapılandırılmış veri ve performans optimizasyonu ile uluslararası görünürlük kuruldu.',
  `content` = '{"description":"İhracat odaklı B2B sitesi: dile göre adres yapısı, yapılandırılmış veri ve performans kurulumu tek projede.","key_features":["Dile göre adres (URL) yapısı","Hreflang ve canonical kurulumu","Ürün ve kurumsal yapılandırılmış veri","Core Web Vitals optimizasyonu","Çok dilli içerik yönetimi"],"technologies_used":["Next.js","Fastify","MySQL","JSON-LD","Lighthouse"],"case_study":{"challenge":"Aynı ürün sayfasının farklı dillerdeki sürümleri birbirinin kopyası gibi algılanıyordu. Ayrıca çeviriler farklı zamanlarda eklendiği için bazı diller eksik kalıyordu.","approach":"Adres yapısını dile göre ayırdık ve her sayfa için dil eşlemesini açıkça tanımladık. İçerik yönetimini, eksik çevirinin görünür olduğu bir yapıya çevirdik; böylece boşluklar takip edilebilir hale geldi.","outcome":"Her pazar kendi diline ait sayfalarla görünür hale geldi; dil sürümleri birbirinin kopyası olarak değerlendirilmiyor. Eksik çeviriler panelden izlenebiliyor."},"html":"<p>Çok dilli B2B sitesi projesinde amaç, farklı pazarlardaki alıcıların markaya kendi dilinde ve doğru içerikle ulaşmasıydı. Teknik kurulum baştan arama ve yapay zekâ görünürlüğü gözetilerek yapıldı.</p>\\n<h2>Proje hakkında</h2>\\n<p>İhracat yapan firmalarda site genellikle tek dilde kurulur, çeviriler sonradan eklenir. Bu yapı arama motorlarında hangi sayfanın hangi pazara ait olduğunu belirsiz bırakır ve içerik birbirini yer.</p>\\n<h2>ihracat odaklı B2B sitesi projesinde çözülen sorun</h2>\\n<p>Aynı ürün sayfasının farklı dillerdeki sürümleri birbirinin kopyası gibi algılanıyordu. Ayrıca çeviriler farklı zamanlarda eklendiği için bazı diller eksik kalıyordu.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Adres yapısını dile göre ayırdık ve her sayfa için dil eşlemesini açıkça tanımladık. İçerik yönetimini, eksik çevirinin görünür olduğu bir yapıya çevirdik; böylece boşluklar takip edilebilir hale geldi.</p>\\n<ul><li>Dil ve pazar haritası çıkarıldı</li><li>Dile göre adres yapısı ve hreflang kuruldu</li><li>Yapılandırılmış veri eklendi</li><li>Performans ve erişilebilirlik ölçümleri iyileştirildi</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Her pazar kendi diline ait sayfalarla görünür hale geldi; dil sürümleri birbirinin kopyası olarak değerlendirilmiyor. Eksik çeviriler panelden izlenebiliyor.</p>\\n<ul><li>Dile göre kanonik adres yapısı</li><li>Dil sürümleri arasında doğru eşleme</li><li>Yapılandırılmış veriyle net ürün tanımı</li><li>Eksik çeviriler görünür ve takip edilebilir</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>Next.js</li><li>Fastify</li><li>MySQL</li><li>JSON-LD</li><li>Lighthouse</li></ul>\\n<p>Site 2026 itibarıyla canlıda ve yeni dil eklemeleri aynı yapıyla ilerliyor. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>Her dil için ayrı site mi kuruldu?</h3>\\n<p>Hayır. Tek kod tabanı ve tek yönetim paneli var; diller aynı içerik yapısının çevirileri olarak yönetiliyor.</p>\\n<h3>Yeni bir dil eklemek ne kadar sürüyor?</h3>\\n<p>Teknik hazırlık hazır olduğu için süre çeviri içeriğinin hazırlanmasına bağlı; teknik tarafta ek kurulum gerekmiyor.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/kurumsal-web-sitesi\\">Kurumsal web sitesi</a> · <a href=\\"/tr/hizmetler/geo-seo-lighthouse-analizi\\">GEO analizi ve SEO denetimi</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'cok-dilli-b2b-sitesi-geo-seo-lighthouse-analizi';

