UPDATE `projects_i18n` SET
  `summary` = 'Fide üretim firması için ürün kataloğu, yönetim paneli ve arama motorlarına uygun dinamik sayfalardan oluşan kurumsal site.',
  `meta_title` = 'Ürün Kataloğu Sitesi: Bereket Fide | GZL Teknoloji',
  `meta_description` = 'Ürün kataloğu sitesi vaka çalışması: fide üretim firması için katalog, admin paneli ve arama motorlarına uygun dinamik sayfa yapısı kuruldu.',
  `content` = '{"description":"Fide üretim firması için ürün kataloğu, yönetim paneli ve arama motorlarına uygun dinamik sayfalardan oluşan kurumsal site.","key_features":["Kategorili ürün kataloğu","Yönetim paneli","Arama motorlarına uygun dinamik sayfalar","İletişim ve talep formu","Mobil uyumlu tasarım"],"technologies_used":["Next.js","Fastify","MySQL","Tailwind CSS","Drizzle ORM"],"case_study":{"challenge":"Ürün sayısı fazlaydı ve her çeşidin kendi özellikleri vardı. Bu yapıyı hem yönetilebilir hem de her ürünün ayrı bir sayfa olarak aranabildiği biçimde kurmak gerekiyordu.","approach":"Ürünleri kategori ve özellik ekseninde modelledik; her çeşit kendi adresine sahip bir sayfa oldu. Panel, sezon başında toplu güncelleme yapmayı kolaylaştıracak biçimde tasarlandı.","outcome":"Her çeşit kendi adresinden bulunabiliyor; güncel liste tek kaynaktan yayınlanıyor. Firma sezon değişiminde kataloğu kendi güncelliyor."},"html":"<p>Ürün kataloğu sitesi, fide üreten bir firmanın çeşit listesini müşterilerine düzenli biçimde sunması için geliştirildi. Katalog, yönetim paneli ve içerik yapısı birlikte kuruldu.</p>\\n<h2>Proje hakkında</h2>\\n<p>Tarım üretiminde çeşit listesi sezona göre değişir; basılı katalog hazırlandığı anda eskimeye başlar. Firma güncel listeyi mesajla paylaşıyordu, bu da hem takip edilemiyor hem de aramalarda hiç görünmüyordu.</p>\\n<h2>ürün kataloğu sitesi projesinde çözülen sorun</h2>\\n<p>Ürün sayısı fazlaydı ve her çeşidin kendi özellikleri vardı. Bu yapıyı hem yönetilebilir hem de her ürünün ayrı bir sayfa olarak aranabildiği biçimde kurmak gerekiyordu.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Ürünleri kategori ve özellik ekseninde modelledik; her çeşit kendi adresine sahip bir sayfa oldu. Panel, sezon başında toplu güncelleme yapmayı kolaylaştıracak biçimde tasarlandı.</p>\\n<ul><li>Ürün ve kategori yapısı çıkarıldı</li><li>Katalog modeli ve yönetim paneli geliştirildi</li><li>Ürün sayfaları arama motorlarına uygun kuruldu</li><li>İçerik aktarıldı ve site yayına alındı</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Her çeşit kendi adresinden bulunabiliyor; güncel liste tek kaynaktan yayınlanıyor. Firma sezon değişiminde kataloğu kendi güncelliyor.</p>\\n<ul><li>Her ürün ayrı sayfa olarak aranabiliyor</li><li>Sezon güncellemesi panelden yapılıyor</li><li>Talep formu ile gelen sorular kayıt altında</li><li>Mobil kullanım öncelikli tasarım</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>Next.js</li><li>Fastify</li><li>MySQL</li><li>Tailwind CSS</li><li>Drizzle ORM</li></ul>\\n<p>Site 2026 itibarıyla canlıda ve katalog düzenli güncelleniyor. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>Ürünler toplu yüklenebiliyor mu?</h3>\\n<p>Evet. Tablo ile toplu aktarım yapılabiliyor; görseller de toplu eşleştiriliyor.</p>\\n<h3>Sonradan e-ticaret eklenebilir mi?</h3>\\n<p>Evet. Katalog yapısı sipariş ve ödeme modülleriyle genişletilebilecek biçimde kuruldu.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/kurumsal-web-sitesi\\">Kurumsal web sitesi</a> · <a href=\\"/tr/hizmetler/e-ticaret-sitesi\\">E-ticaret sitesi kurulumu</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'bereket-fide-kurumsal-web-sitesi-urun-katalogu';

