UPDATE `projects_i18n` SET
  `summary` = 'Spor giyim, supplement ve outdoor ürünlerini listeleyen çok kategorili e-ticaret platformu.',
  `meta_title` = 'Spor E-Ticaret Platformu: Sportoonline | GZL Teknoloji',
  `meta_description` = 'Spor e-ticaret platformu vaka çalışması: çok kategorili ürün yapısı, sepet, kupon ve mağaza yönetimi tek sistemde kuruldu.',
  `content` = '{"description":"Spor giyim, supplement ve outdoor ürünlerini listeleyen çok kategorili e-ticaret platformu.","key_features":["Çok kategorili ürün yapısı","Varyant ve stok yönetimi","Sepet, kupon ve kampanya","Sipariş yönetimi","Mağaza ve içerik yönetimi"],"technologies_used":["Next.js","Fastify","MySQL","Drizzle ORM","Tailwind CSS","Cloudinary"],"case_study":{"challenge":"Kategoriler arasında ortak olmayan özellikler yüzünden filtreleme karmaşıklaşıyordu. Ayrıca kampanya kurgularının kategori bazlı çalışması gerekiyordu.","approach":"Ürün modelini çekirdek alanlar ve kategoriye özel alanlar olarak ikiye ayırdık. Filtreler kategori bağlamında üretiliyor; kampanya kuralları da aynı yapıdan besleniyor.","outcome":"Farklı ürün grupları aynı mağazada, kendi mantığına uygun biçimde listeleniyor. Kampanyalar kategori bazında tanımlanabiliyor ve sipariş akışı tek panelden izleniyor."},"html":"<p>Spor e-ticaret platformu, farklı ürün gruplarını tek mağazada toplayan bir satış kanalı kurmak için geliştirildi. Ürün yapısı, sepet akışı ve yönetim paneli birlikte tasarlandı.</p>\\n<h2>Proje hakkında</h2>\\n<p>Spor giyim, supplement ve outdoor ürünleri farklı özellik setlerine sahiptir: birinde beden, diğerinde tat ve gramaj belirleyicidir. Tek bir ürün modeliyle bu farklılıkları taşımak projenin merkezindeki konuydu.</p>\\n<h2>spor e-ticaret platformu projesinde çözülen sorun</h2>\\n<p>Kategoriler arasında ortak olmayan özellikler yüzünden filtreleme karmaşıklaşıyordu. Ayrıca kampanya kurgularının kategori bazlı çalışması gerekiyordu.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Ürün modelini çekirdek alanlar ve kategoriye özel alanlar olarak ikiye ayırdık. Filtreler kategori bağlamında üretiliyor; kampanya kuralları da aynı yapıdan besleniyor.</p>\\n<ul><li>Kategori ve özellik matrisi çıkarıldı</li><li>Ürün modeli ve varyant yapısı kuruldu</li><li>Sepet, kupon ve sipariş akışı geliştirildi</li><li>Test siparişleriyle uçtan uca doğrulandı</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Farklı ürün grupları aynı mağazada, kendi mantığına uygun biçimde listeleniyor. Kampanyalar kategori bazında tanımlanabiliyor ve sipariş akışı tek panelden izleniyor.</p>\\n<ul><li>Kategoriye özel filtreler</li><li>Varyant yönetimi tek yerde</li><li>Kampanya kuralları esnek</li><li>Sipariş süreci uçtan uca izlenebiliyor</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>Next.js</li><li>Fastify</li><li>MySQL</li><li>Drizzle ORM</li><li>Tailwind CSS</li><li>Cloudinary</li></ul>\\n<p>Platform 2026 itibarıyla canlıda ve ürün kataloğu genişletiliyor. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>Ürün sayısı arttığında yavaşlar mı?</h3>\\n<p>Listeleme ve filtreleme sunucu tarafında yapıldığı ve önbelleklendiği için ürün sayısının artması kullanıcı deneyimini bozmuyor.</p>\\n<h3>Pazar yeri entegrasyonu mümkün mü?</h3>\\n<p>Evet. Ürün ve stok verisi arayüz üzerinden dışa açılabildiği için pazar yeri entegrasyonları eklenebiliyor.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/modern-e-ticaret-sitesi\\">Modern e-ticaret sitesi</a> · <a href=\\"/tr/hizmetler/e-ticaret-sitesi\\">E-ticaret sitesi kurulumu</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'sportoonline-spor-outdoor-e-ticaret-platformu';

