UPDATE `projects_i18n` SET
  `summary` = 'Portföy yönetimi, çok dilli arayüz ve ödeme entegrasyonu içeren emlak ilan ve gayrimenkul yönetim platformu.',
  `meta_title` = 'Emlak İlan Platformu: Kamanilan | GZL Teknoloji',
  `meta_description` = 'Emlak ilan platformu vaka çalışması: portföy yönetimi, çok dilli arayüz, ödeme entegrasyonu ve yönetim paneli tek sistemde birleştirildi.',
  `content` = '{"description":"Portföy yönetimi, çok dilli arayüz ve ödeme entegrasyonu içeren emlak ilan ve gayrimenkul yönetim platformu.","key_features":["İlan ve portföy yönetimi","Gelişmiş arama ve filtreleme","Çok dilli arayüz","Ödeme entegrasyonu","Yönetim paneli"],"technologies_used":["Next.js","React","TypeScript","Fastify","Drizzle ORM","MySQL","Iyzipay"],"case_study":{"challenge":"İlan verisi çok alanlıdır ve filtreleme mantığı bu alanlar üzerine kurulur; alan yapısı baştan yanlış tasarlanırsa sonradan değiştirmek tüm ilanların güncellenmesini gerektirir.","approach":"Alan yapısını ilan tipine göre ayırdık: konut, iş yeri ve arsa farklı alan setleriyle çalışıyor. Arama ve filtreleme bu yapıdan otomatik üretiliyor.","outcome":"Portföy kendi adresinde yayınlanıyor ve gelen talep doğrudan ofise ulaşıyor. İlan tipine göre filtreleme, arayan kişinin doğru kayda hızlı ulaşmasını sağlıyor."},"html":"<p>Emlak ilan platformu, portföyün ilan sitelerine bağımlı kalmadan kendi kanalında yayınlanması için geliştirildi. İlan yönetimi, arama ve ödeme akışı tek sistemde çalışıyor.</p>\\n<h2>Proje hakkında</h2>\\n<p>İlan platformları görünürlük sağlar ama müşteri ilişkisi orada kalır ve her ilan için ücret ödenir. Kendi platformu olan ofis, arama motorlarından gelen talebi doğrudan alır ve portföyünü kalıcı bir varlığa çevirir.</p>\\n<h2>emlak ilan platformu projesinde çözülen sorun</h2>\\n<p>İlan verisi çok alanlıdır ve filtreleme mantığı bu alanlar üzerine kurulur; alan yapısı baştan yanlış tasarlanırsa sonradan değiştirmek tüm ilanların güncellenmesini gerektirir.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Alan yapısını ilan tipine göre ayırdık: konut, iş yeri ve arsa farklı alan setleriyle çalışıyor. Arama ve filtreleme bu yapıdan otomatik üretiliyor.</p>\\n<ul><li>İlan tipleri ve alan setleri belirlendi</li><li>İlan yönetimi ve arama altyapısı kuruldu</li><li>Çok dilli arayüz ve ödeme akışı eklendi</li><li>Portföy aktarıldı ve site yayına alındı</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Portföy kendi adresinde yayınlanıyor ve gelen talep doğrudan ofise ulaşıyor. İlan tipine göre filtreleme, arayan kişinin doğru kayda hızlı ulaşmasını sağlıyor.</p>\\n<ul><li>İlan tipine göre doğru filtreler</li><li>Talepler doğrudan ofise ulaşıyor</li><li>Çok dilli kullanım</li><li>Ödeme akışı entegre</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>Next.js</li><li>React</li><li>TypeScript</li><li>Fastify</li><li>Drizzle ORM</li><li>MySQL</li><li>Iyzipay</li></ul>\\n<p>Platform 2026 itibarıyla kamanilan.com adresinde canlıdır. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>İlanlar dış platformlarla eşitlenebiliyor mu?</h3>\\n<p>Kaynak sistemde arayüz varsa düzenli eşitleme kurulabiliyor; yoksa ilanlar panelden yönetiliyor.</p>\\n<h3>Danışman bazlı yönetim var mı?</h3>\\n<p>Evet. İlanlar danışmana atanabiliyor ve performans danışman bazında raporlanabiliyor.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/emlak-ilan-sitesi\\">Emlak ilan sitesi</a> · <a href=\\"/tr/hizmetler/kurumsal-web-sitesi\\">Kurumsal web sitesi</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'kamanilan';

UPDATE `projects` pr
  JOIN `projects_i18n` i ON i.project_id = pr.id AND i.locale = 'tr'
  SET pr.`client_name` = 'Kamanilan',
      pr.`techs` = '["Next.js","React","TypeScript","Fastify","Drizzle ORM","MySQL","Iyzipay"]',
