  WHERE i.slug = 'kamanilan';

UPDATE `projects_i18n` SET
  `summary` = 'Bonn merkezli bir masaj ve wellness merkezi için çok dilli kurumsal site, online randevu ve hizmet yönetimi.',
  `meta_title` = 'Online Randevu Sitesi: Königs Massage | GZL Teknoloji',
  `meta_description` = 'Online randevu sitesi vaka çalışması: çok dilli wellness sitesi, takvim yönetimi ve otomatik hatırlatmalarla telefon trafiği belirgin biçimde azaldı.',
  `content` = '{"description":"Bonn merkezli bir masaj ve wellness merkezi için çok dilli kurumsal site, online randevu ve hizmet yönetimi.","key_features":["Online randevu ve takvim yönetimi","Çok dilli (TR/DE) içerik","Hizmet ve personel yönetimi","Otomatik onay ve hatırlatma","Yapay zekâ destekli sohbet yanıtları"],"technologies_used":["Next.js","Fastify","MySQL","Drizzle ORM","Nodemailer"],"case_study":{"challenge":"Çalışma saatleri, hizmet süreleri ve personel müsaitliği birbirine bağlıydı; kurallar yanlış kurulduğunda aynı saate iki randevu düşme riski vardı. Ayrıca içerik iki dilde sunulacaktı.","approach":"Takvim kurallarını hizmet süresi ve personel müsaitliği üzerinden modelledik ve canlıya geçmeden gerçek senaryolarla test ettik. Bildirimler onay ve hatırlatma olmak üzere iki aşamaya ayrıldı.","outcome":"Randevular mesai dışında da alınabiliyor; hatırlatmalar sayesinde gelmeyen müşteri oranı düştü. Telefon trafiği azaldı ve takvim tek ekrandan yönetiliyor."},"html":"<p>Online randevu sitesi, mesai dışında gelen taleplerin kaybolmaması ve takvimin tek yerden yönetilmesi için geliştirildi. Site, randevu akışı ve bildirimler birlikte kuruldu.</p>\\n<h2>Proje hakkında</h2>\\n<p>Randevuyla çalışan işletmelerde en büyük kayıp, cevaplanamayan telefonlar ve gelmeyen müşterilerdir. Merkez randevuları telefonla alıyor, seans sırasında gelen aramaları karşılayamıyordu.</p>\\n<h2>online randevu sitesi projesinde çözülen sorun</h2>\\n<p>Çalışma saatleri, hizmet süreleri ve personel müsaitliği birbirine bağlıydı; kurallar yanlış kurulduğunda aynı saate iki randevu düşme riski vardı. Ayrıca içerik iki dilde sunulacaktı.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Takvim kurallarını hizmet süresi ve personel müsaitliği üzerinden modelledik ve canlıya geçmeden gerçek senaryolarla test ettik. Bildirimler onay ve hatırlatma olmak üzere iki aşamaya ayrıldı.</p>\\n<ul><li>Hizmet listesi, süreler ve çalışma saatleri tanımlandı</li><li>Takvim ve çakışma kontrolü kuruldu</li><li>Çok dilli site içeriği hazırlandı</li><li>Bildirim kanalları bağlanıp canlıya geçildi</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Randevular mesai dışında da alınabiliyor; hatırlatmalar sayesinde gelmeyen müşteri oranı düştü. Telefon trafiği azaldı ve takvim tek ekrandan yönetiliyor.</p>\\n<ul><li>Mesai dışı randevu alımı</li><li>Otomatik onay ve hatırlatma</li><li>Çakışma kontrolü ile çift rezervasyon yok</li><li>İki dilli kullanım</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>Next.js</li><li>Fastify</li><li>MySQL</li><li>Drizzle ORM</li><li>Nodemailer</li></ul>\\n<p>Site 2026 itibarıyla canlıda ve randevular sistem üzerinden alınıyor. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>Müşteri randevusunu kendisi iptal edebiliyor mu?</h3>\\n<p>Evet, belirlenen süre sınırına kadar. İptal ve erteleme kuralları panelden yönetiliyor.</p>\\n<h3>Dış takvimlerle eşleşiyor mu?</h3>\\n<p>Takvim uygulamalarıyla eşleme kurulabiliyor; böylece dışarıda alınan randevular da müsaitliğe yansıyor.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/randevu-sistemli-kurumsal-site\\">Randevu sistemli web sitesi</a> · <a href=\\"/tr/hizmetler/kurumsal-web-sitesi\\">Kurumsal web sitesi</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'konig-energetik-randevulu-masaj-wellness-sitesi';

