UPDATE `projects_i18n` SET
  `summary` = 'Et ve balık restoranı için QR menü destekli, hızlı açılan tek sayfa tanıtım sitesi.',
  `meta_title` = 'Restoran Tanıtım Sitesi: Miss Et & Balık | GZL',
  `meta_description` = 'Restoran tanıtım sitesi vaka çalışması: tek sayfa yapı, QR menü desteği ve hızlı açılışla mekân tanıtımı ve menü erişimi birleştirildi.',
  `content` = '{"description":"Et ve balık restoranı için QR menü destekli, hızlı açılan tek sayfa tanıtım sitesi.","key_features":["Tek sayfa tanıtım yapısı","QR menü erişimi","Hızlı açılış ve düşük kaynak kullanımı","Mobil öncelikli tasarım","İletişim ve yol tarifi"],"technologies_used":["HTML5","CSS3","JavaScript","Nginx","SSL"],"case_study":{"challenge":"Ziyaretçilerin büyük bölümü mobil ve çoğu zaman zayıf bağlantıyla geliyordu. Sayfanın hızlı açılması, görsellerin ise mekânı iyi anlatması gerekiyordu; bu iki ihtiyaç birbirine zıttı.","approach":"Görselleri boyut ve biçim olarak optimize ettik, betik kullanımını en aza indirdik. Menüye erişimi QR kod üzerinden doğrudan verdik; böylece masadaki ziyaretçi ek adım yaşamıyor.","outcome":"Sayfa zayıf bağlantıda da hızlı açılıyor; menüye erişim tek adıma indi. Bakım yükü neredeyse yok, güncelleme ihtiyacı düşük."},"html":"<p>Restoran tanıtım sitesi, mekânı anlatan ve menüye hızlı erişim veren sade bir yapı olarak kuruldu. Ağır bir altyapı yerine hızlı açılan tek sayfa tercih edildi.</p>\\n<h2>Proje hakkında</h2>\\n<p>Küçük ölçekli bir restoran için ziyaretçinin ihtiyacı sınırlıdır: menü, konum ve iletişim. Bu ihtiyaç için içerik yönetim sistemi kurmak gereksiz bir bakım yükü yaratır.</p>\\n<h2>restoran tanıtım sitesi projesinde çözülen sorun</h2>\\n<p>Ziyaretçilerin büyük bölümü mobil ve çoğu zaman zayıf bağlantıyla geliyordu. Sayfanın hızlı açılması, görsellerin ise mekânı iyi anlatması gerekiyordu; bu iki ihtiyaç birbirine zıttı.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Görselleri boyut ve biçim olarak optimize ettik, betik kullanımını en aza indirdik. Menüye erişimi QR kod üzerinden doğrudan verdik; böylece masadaki ziyaretçi ek adım yaşamıyor.</p>\\n<ul><li>İçerik ve görsel seçimi yapıldı</li><li>Tek sayfa yapı kuruldu</li><li>Görseller optimize edildi</li><li>QR menü bağlantısı ve yayın tamamlandı</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Sayfa zayıf bağlantıda da hızlı açılıyor; menüye erişim tek adıma indi. Bakım yükü neredeyse yok, güncelleme ihtiyacı düşük.</p>\\n<ul><li>Hızlı açılış, düşük kaynak kullanımı</li><li>Masadan QR ile doğrudan menü</li><li>Mobil öncelikli görünüm</li><li>Düşük bakım yükü</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>HTML5</li><li>CSS3</li><li>JavaScript</li><li>Nginx</li><li>SSL</li></ul>\\n<p>Site 2026 itibarıyla yayında ve menü bağlantısı güncel tutuluyor. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>Neden içerik yönetim sistemi kullanılmadı?</h3>\\n<p>İçerik nadiren değiştiği için panel kurmak gereksiz bakım yükü yaratacaktı. İhtiyaç büyürse yapı taşınabilir.</p>\\n<h3>Online sipariş eklenebilir mi?</h3>\\n<p>Evet. Sipariş akışı ayrı bir modül olarak eklenebiliyor; bunun için sipariş sistemi hizmetimize bakabilirsiniz.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/online-siparis-sistemi\\">Online sipariş sistemi</a> · <a href=\\"/tr/hizmetler/kurumsal-web-sitesi\\">Kurumsal web sitesi</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'miss-et-balik';

