UPDATE `projects_i18n` SET
  `summary` = 'Hizmet kataloğu, paket satışı ve içerik yönetimini birleştiren kurumsal satış sitesi; tek kod tabanı iki markayı ayrı veritabanlarıyla sunuyor.',
  `meta_title` = 'Kurumsal Satış Sitesi: gzlteknoloji.com | GZL Teknoloji',
  `meta_description` = 'Kurumsal satış sitesi vaka çalışması: hizmet kataloğu, paket satışı ve içerik yönetimi tek kod tabanında iki marka için ayrı ayrı sunuldu.',
  `content` = '{"description":"Hizmet kataloğu, paket satışı ve içerik yönetimini birleştiren kurumsal satış sitesi; tek kod tabanı iki markayı ayrı veritabanlarıyla sunuyor.","key_features":["Hizmet ve paket kataloğu","Portfolyo ve referans yönetimi","Blog ve içerik modülü","Çok dilli yapı","Yönetim paneli"],"technologies_used":["Next.js","React","TypeScript","Fastify","Drizzle ORM","MySQL","Bun"],"case_study":{"challenge":"İki marka aynı kod tabanını paylaşacaktı ama içerik, logo, adres ve dil varsayılanları tamamen farklıydı. Kod tarafında sabit yazılmış her marka verisi yanlış sitede görünme riski taşıyordu.","approach":"Marka verisini tamamen veritabanına taşıdık; kod tabanında marka adı, adres veya logo sabit yazılmıyor. Dağıtım profili hangi veritabanına bağlanacağını ve varsayılan dili belirliyor.","outcome":"Tek kod tabanı iki markayı birbirine karıştırmadan sunuyor. Yeni bir marka eklemek yeni bir kod tabanı değil, yeni bir profil ve içerik seti anlamına geliyor."},"html":"<p>Kurumsal satış sitesi, hizmetleri ürünleştirip paket olarak sunmak için kuruldu. Aynı kod tabanı iki ayrı markayı, ayrı veritabanlarıyla ve ayrı içerikle sunuyor.</p>\\n<h2>Proje hakkında</h2>\\n<p>Ajans ve yazılım firmalarında hizmetler genellikle serbest tanımlıdır; bu da her teklifi sıfırdan hazırlamayı gerektirir. Site, hizmetleri kapsamı ve süresi belli paketlere dönüştürmek üzere kurgulandı.</p>\\n<h2>kurumsal satış sitesi projesinde çözülen sorun</h2>\\n<p>İki marka aynı kod tabanını paylaşacaktı ama içerik, logo, adres ve dil varsayılanları tamamen farklıydı. Kod tarafında sabit yazılmış her marka verisi yanlış sitede görünme riski taşıyordu.</p>\\n<h2>Nasıl çözdük</h2>\\n<p>Marka verisini tamamen veritabanına taşıdık; kod tabanında marka adı, adres veya logo sabit yazılmıyor. Dağıtım profili hangi veritabanına bağlanacağını ve varsayılan dili belirliyor.</p>\\n<ul><li>Ortak kod tabanı ve profil ayrımı kuruldu</li><li>Marka verisi veritabanına taşındı</li><li>Hizmet ve paket katalogları oluşturuldu</li><li>İki site ayrı ayrı yayına alındı</li></ul>\\n<h2>Sonuçlar</h2>\\n<p>Tek kod tabanı iki markayı birbirine karıştırmadan sunuyor. Yeni bir marka eklemek yeni bir kod tabanı değil, yeni bir profil ve içerik seti anlamına geliyor.</p>\\n<ul><li>Marka verisi kodda değil veritabanında</li><li>Profil bazlı dağıtım</li><li>Hizmetler paket olarak satılabiliyor</li><li>İçerik panelden yönetiliyor</li></ul>\\n<h2>Kullanılan teknolojiler</h2>\\n<ul><li>Next.js</li><li>React</li><li>TypeScript</li><li>Fastify</li><li>Drizzle ORM</li><li>MySQL</li><li>Bun</li></ul>\\n<p>Site 2026 itibarıyla gzlteknoloji.com adresinde canlıdır. Bu çalışma GZL Teknoloji tarafından yürütülmüştür.</p>\\n<h2>Sıkça Sorulan Sorular</h2>\\n<h3>İki site aynı veritabanını mı kullanıyor?</h3>\\n<p>Hayır. Her marka kendi veritabanına sahip; ortak olan yalnızca kod tabanı.</p>\\n<h3>Yeni marka eklemek ne gerektiriyor?</h3>\\n<p>Yeni bir dağıtım profili, kendi veritabanı ve kendi içerik seti. Kod tarafında değişiklik gerekmiyor.</p>\\n<p>İlgili sayfalar: <a href=\\"/tr/hizmetler/kurumsal-web-sitesi\\">Kurumsal web sitesi</a> · <a href=\\"/tr/hizmetler/ozel-yazilim-nextjs-fastify\\">Özel yazılım geliştirme</a> · <a href=\\"/tr/portfolyo\\">Tüm referanslar</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>"}',
  `updated_at` = CURRENT_TIMESTAMP(3)
WHERE `locale` = 'tr' AND `slug` = 'gzlteknoloji';

